import React from 'react'

function About() {
  return (
    <div>
        <h1 className="about-header">About Me</h1>
        <section className="about-container">
            <p>
                My name is Kian Javaheri. I'm an aspiring back-end software engineer from the Bay Area in California. Currently, I am studying computer science with a minor in cognitive science at the University of Minnesota-Twin Cities.
            </p>
        </section>

    </div>
  )
}

export default About;
